// Aurora visual identity: build-time colour + typeface remap.
//
// The site's CSS/JS/HTML is generated by the importer, so instead of hand-editing hundreds of files
// the build rewrites the old brand palette and typefaces into the aurora system as it writes dist/.
// Only colour values and font-family names change; markup, content and layout are untouched.
// Image/SVG asset files are never rewritten.

// old hex -> aurora hex (matched case-insensitively, full 6-digit values only)
export const PALETTE = {
  // teal accents -> turquoise / violet
  '3ABDBC': '40E0D0', // primary accent -> aurora turquoise
  '3BADBC': '3CCFCB',
  '71C7D2': 'A78BFA', // light accent -> lavender violet
  'BFEFEF': 'DCD3FF', // pale accent -> lavender mist
  'BFEBEF': 'DDD6FE',
  'DAEFF3': 'EDE9FE',
  '1E9E9F': '14B8A6', // teal
  '1F7F7E': '4C51D9', // deep teal -> indigo
  '10758B': '6D5DF6', // secondary -> indigo-violet
  '00788E': '5B4FE0',
  '134872': '312E81', // navy -> deep indigo
  // warm accents -> soft pink / rose
  'E97845': 'E86AA6',
  'F37039': 'E9629F',
  'E67A57': 'E57AA6',
  'FDC713': 'F9A8D4',
  'F8C811': 'F9A8D4',
  // charcoal grounds -> midnight blue
  '151920': '0A0D24',
  '1C2028': '11163A',
  '23272F': '171D45',
  '2C3039': '1F2652',
};

// "r,g,b" triplets used inside rgb()/rgba()
const RGB = {
  '58,189,188': '64,224,208',
  '59,173,188': '60,207,203',
  '113,199,210': '167,139,250',
  '16,117,139': '109,93,246',
  '233,120,69': '232,106,166',
  '243,112,57': '233,98,159',
  '21,25,32': '10,13,36',
  '28,32,40': '17,22,58',
  '35,39,47': '23,29,69',
};

export const FONTS = [
  [/(['"]?)Open Sans\1/g, '$1Inter$1'],
  [/(['"]?)Space Grotesk\1/g, '$1Sora$1'],
  [/(['"]?)Montserrat\1/g, '$1Inter$1'],
];

const hexRe = new RegExp(`#(${Object.keys(PALETTE).join('|')})(?![0-9a-f])`, 'gi');
const rgbRe = new RegExp(`(rgba?\\(\\s*)(${Object.keys(RGB).map(k => k.split(',').join('\\s*,\\s*')).join('|')})`, 'gi');

export function auroraize(text) {
  let out = text.replace(hexRe, (_, h) => '#' + PALETTE[h.toUpperCase()]);
  out = out.replace(rgbRe, (_, pre, trip) => pre + RGB[trip.replace(/\s+/g, '')]);
  for (const [re, to] of FONTS) out = out.replace(re, to);
  return out;
}

export const AURORA_EXTS = new Set(['.css', '.js', '.html']);
